// <auto-imports> — generated by wire.mjs, do not edit by hand
import { getOwnedActor } from "./actors.js";
import { MODULE_ID } from "./constants.js";
import { spellcastingInfo, spellcastingPreparation } from "./items.js";
import { buildHitDiceDto } from "./map.js";
import { escapeHtml } from "./media.js";
import { APPROVAL_LOG_FOLDER } from "./offline.js";
import { iterItemActivities, resolveItemTemplateSpec } from "./templates.js";
// </auto-imports>
// Character sheet build + inventory/journals/spells/features/biography — extracted from mobile-bridge.js.

export function numericBonus(field) {
  if (field == null) return 0;
  if (typeof field === "number" && Number.isFinite(field)) return field;
  if (typeof field === "object" && field !== null && "value" in field) {
    const v = field.value;
    return typeof v === "number" && Number.isFinite(v) ? v : 0;
  }
  return 0;
}

/** Numeric part of a dnd5e FormulaField (e.g. init.bonus) for mobile display/edit. */
export function formulaBonusNumeric(field, actor) {
  if (field == null || field === "") return 0;
  if (typeof field === "number" && Number.isFinite(field)) return field;
  const simplify = globalThis.dnd5e?.utils?.simplifyBonus;
  if (typeof simplify === "function" && actor) {
    const n = simplify(field, actor.getRollData?.() ?? {});
    return typeof n === "number" && Number.isFinite(n) ? n : 0;
  }
  const asNum = Number(field);
  return Number.isFinite(asNum) ? asNum : 0;
}

/**
 * The *source* max-HP override, i.e. what the user typed into dnd5e's
 * "Hit Points Override" field. `actor.system.attributes.hp.max` is derived
 * (prepareHitPoints overwrites it with the auto-calculated total when the
 * source is null), so the raw document is the only place the distinction
 * between "override 42" and "auto, currently 42" survives.
 */
export function hpMaxOverrideOf(actor) {
  const raw = actor?._source?.system?.attributes?.hp?.max;
  return Number.isFinite(raw) ? Math.floor(raw) : null;
}

/** Map dnd5e skill.value (0 / 0.5 / 1 / 2) → mobile tiers none / proficient / expertise. */
export function skillProficiencyTier(value) {
  const n = typeof value === "number" && Number.isFinite(value) ? value : 0;
  if (n >= 2) return 2;
  if (n >= 1) return 1;
  return 0;
}

export function buildBasicSheet(user, actorId) {
  const actor = getOwnedActor(user, actorId);
  const system = actor.system ?? {};
  const rawAbilities = system.abilities ?? {};
  const rawSkills = system.skills ?? {};
  const attributes = system.attributes ?? {};
  const details = system.details ?? {};

  const abilities = Object.fromEntries(
    Object.entries(rawAbilities).map(([key, ab]) => [
      key,
      {
        score: ab.value ?? 0,
        mod: numericBonus(ab.mod),
        saveMod: numericBonus(ab.save),
        // dnd5e save proficiency is binary (0/1), unlike skills which also
        // carry expertise (2). The phone renders and edits it as such.
        saveProf: ab.proficient ? 1 : 0
      }
    ])
  );

  const skills = Object.fromEntries(
    Object.entries(rawSkills).map(([key, sk]) => [
      key,
      {
        total: numericBonus(sk.total),
        passive: sk.passive == null ? 10 : numericBonus(sk.passive),
        ability: sk.ability ?? "",
        label: game.i18n.localize(CONFIG.DND5E.skills[key]?.label ?? key),
        proficiency: skillProficiencyTier(sk.value)
      }
    ])
  );

  // Equipped weapons + activatable features
  // In dnd5e v4 weapon damage lives on system.damage.base (DamageField), not system.damage.parts
  const items = actor.items
    .filter(i =>
      (i.type === "weapon" && i.system.equipped) ||
      (i.type === "feat" && i.system.activation?.type)
    )
    .map(i => ({
      id: i.id,
      name: i.name,
      type: i.type,
      damage: i.type === "weapon" ? (i.system.damage?.base?.formula || null) : null
    }));

  // All spells known/prepared
  const spells = actor.items
    .filter(i => i.type === "spell")
    .map(i => ({
      id: i.id,
      name: i.name,
      level: i.system.level ?? 0,
      school: i.system.school ?? ""
    }));

  // Class items (for the level-up wizard). One row per class the actor has,
  // with the current level and the hit-die label. Used by the mobile UI to
  // pick which class to advance.
  const classes = actor.items
    .filter(i => i.type === "class")
    .map(i => ({
      id: i.id,
      name: i.name,
      level: i.system?.levels ?? 0,
      hitDie: i.system?.hd?.denomination ?? null
    }));

  // Class resources (e.g. Second Wind, Action Surge). Spell slots are shown
  // separately on the Spells tab via actor.spells.list, so we don't duplicate
  // them here.
  const resources = [];
  for (const res of Object.values(system.resources ?? {})) {
    if (res.label && (res.max ?? 0) > 0) {
      resources.push({ label: res.label, value: res.value ?? 0, max: res.max });
    }
  }

  // Active temporary effects visible on the token — includes core statuses
  // (poisoned, prone, …) and any other temporary ActiveEffects (buffs, debuffs
  // from items/spells/modules). We resolve the image path through
  // foundry.utils.getRoute so any configured route prefix is honoured, then
  // the mobile client prepends the server origin to render the icon.
  const conditions = [];
  try {
    const temp = actor.temporaryEffects ?? [];
    for (const effect of temp) {
      const rawImg = effect.img ?? effect.icon ?? null;
      const routed = routeAssetPath(rawImg);
      const statuses = effect.statuses instanceof Set
        ? [...effect.statuses]
        : Array.isArray(effect.statuses) ? effect.statuses : [];
      conditions.push({
        id: effect.id ?? (statuses[0] ?? effect.name ?? ""),
        name: effect.name ?? "",
        img: routed,
        statuses
      });
    }
  } catch (err) {
    console.warn(`[${MODULE_ID}] temporaryEffects read failed`, err);
  }

  return {
    actorId: actor.id,
    name: actor.name,
    type: actor.type,
    img: routeActorPortrait(actor),
    level: details.level ?? null,
    abilities,
    skills,
    attributes: {
      ac: attributes.ac?.value ?? null,
      speed: attributes.movement?.walk ?? null,
      proficiency: typeof attributes.prof === "number" ? attributes.prof : 0,
      hp: {
        value: attributes.hp?.value ?? null,
        // Derived max (override if one is set, otherwise the calculated total).
        max: attributes.hp?.max ?? null,
        temp: attributes.hp?.temp ?? 0,
        // null when dnd5e is auto-calculating; a number when the sheet's
        // "Hit Points Override" is set. The phone needs both to show which is which.
        maxOverride: hpMaxOverrideOf(actor)
      },
      hd: buildHitDiceDto(actor),
      init: {
        ability: attributes.init?.ability
          || (CONFIG.DND5E?.defaultAbilities?.initiative ?? "dex"),
        bonus: formulaBonusNumeric(attributes.init?.bonus, actor)
      },
      // Attunement slots (used/max) and prepared-spell counts (used/max across
      // spellcasting classes) drive the phone's toggles and their limits.
      attunement: {
        value: attributes.attunement?.value ?? 0,
        max: attributes.attunement?.max ?? 0
      },
      preparation: spellcastingPreparation(actor),
      spellcasting: spellcastingInfo(actor)
    },
    items,
    spells,
    resources,
    conditions,
    classes
  };
}

/**
 * Absolute URLs must not be routed: `getRoute` prepends the world's route
 * prefix, turning `https://host/x.png` into `/https://host/x.png`, which the
 * phone then glues onto its own base URL and requests from the wrong server.
 * Foundry stores such values whenever art is imported from an external source.
 */
export function routeAssetPath(raw) {
  if (typeof raw !== "string" || !raw.length) return null;
  if (/^(https?:)?\/\//i.test(raw) || raw.startsWith("data:")) return raw;
  return foundry.utils.getRoute(raw);
}

export function routeDocumentImg(doc) {
  const raw = doc?.img ?? null;
  return raw ? routeAssetPath(raw) : null;
}

/**
 * Actor sheet portrait — Foundry stores this on ActorDocument.img (Actor.thumbnail).
 * Token artwork lives on prototypeToken.texture.src and is a separate field (see actor-sheet / actor-directory).
 */
export function routeActorPortrait(actor) {
  const raw = actor?.img;
  if (typeof raw !== "string" || !raw.length) return null;
  const defaultImg = actor.constructor.getDefaultArtwork(actor._source).img;
  if (raw === defaultImg) return null;
  return routeAssetPath(raw);
}

export function stripHtmlText(text) {
  return String(text ?? "")
    .replace(/<[^>]*>/g, " ")
    .replace(/&nbsp;/gi, " ")
    .replace(/\s+/g, " ")
    .trim();
}

export function formatWeaponDamageLabel(item) {
  if (item.type !== "weapon") return "";
  const labelDamage = item.labels?.damage;
  const base = item.system?.damage?.base ?? {};
  let formula = base.custom?.enabled ? base.custom.formula : null;
  if (!formula && base.number && base.denomination) {
    formula = `${base.number}d${base.denomination}`;
  }
  if (!formula) formula = labelDamage;
  if (!formula) return "";
  formula = String(formula)
    .replace(/\[.*?\]/g, "")
    .replace(/\s*\+\s*@mod(?:\.[a-z]+)?/gi, "")
    .replace(/\s*\+\s*@abilities\.[^+\s]+/gi, "")
    .trim();
  const types = base.types ?? [];
  const type = types.length ? String(types[0]) : "";
  if (type && !formula.toLowerCase().includes(type.toLowerCase())) {
    return `${formula} ${type}`;
  }
  return formula;
}

export function formatItemRangeLabel(item) {
  if (item.type !== "weapon") return "";
  const labelRange = item.labels?.range;
  if (labelRange) return String(labelRange);
  const range = item.system?.range ?? {};
  const value = range.value;
  if (value == null || value === 0 || value === "") return "melee";
  const units = range.units ?? "ft";
  const long = range.long;
  if (long && Number(long) > Number(value)) return `${value}/${long} ${units}`;
  return `${value} ${units}`;
}

export function formatSpellRangeLabel(item) {
  const labelRange = item.labels?.range;
  if (labelRange) return String(labelRange);
  const range = item.system?.range ?? {};
  const value = range.value;
  if (value == null || value === "") return "";
  const units = range.units ?? "ft";
  return `${value} ${units}`;
}

export function formatSpellDamageLabel(item) {
  const labelDamage = item.labels?.damage;
  if (labelDamage) return String(labelDamage);
  for (const act of iterItemActivities(item.system)) {
    const parts = act?.damage?.parts ?? act?.damage?.onSave?.parts;
    if (Array.isArray(parts) && parts.length > 0) {
      const part = parts[0];
      if (Array.isArray(part) && part[0]) return String(part[0]);
      if (typeof part === "string") return part;
    }
  }
  return "";
}

/**
 * List inventory items for an actor (weapons, equipment, consumables, tools, loot, etc.)
 * Excludes spells and class features (those are on the sheet already).
 */
export function listInventory(user, actorId) {
  const actor = getOwnedActor(user, actorId);
  const INVENTORY_TYPES = new Set(["weapon", "equipment", "consumable", "tool", "loot", "container", "backpack"]);
  const items = [];
  const actorCurrency = actor.system?.currency ?? {};
  const currencyConfig = CONFIG.DND5E?.currencies ?? {};
  const currencyKeys = [
    ...Object.keys(currencyConfig),
    ...Object.keys(actorCurrency).filter((key) => !(key in currencyConfig))
  ];
  const currency = currencyKeys.map((key) => {
    const cfg = currencyConfig[key] ?? {};
    return {
      key,
      label: game.i18n.localize(cfg.label ?? key),
      abbreviation: game.i18n.localize(cfg.abbreviation ?? key),
      value: Number(actorCurrency[key] ?? 0) || 0
    };
  });
  const allItems = actor.items.contents ?? [...actor.items.values()];
  for (const item of allItems) {
    if (!INVENTORY_TYPES.has(item.type)) continue;
    const act = item.system.activation;
    const hasAction = act && act.type && act.type !== "none";
    const description = stripHtmlText(item.system.description?.value);
    // dnd5e's "chat description" doubles as the player-written short line; the
    // GM sees the same field on the item sheet, unlike a module flag would be.
    const chatDescription = stripHtmlText(item.system.description?.chat);
    items.push({
      id: item.id,
      name: item.name,
      type: item.type,
      img: routeDocumentImg(item),
      equipped: item.system.equipped ?? false,
      canEquip: "equipped" in (item.system ?? {}),
      quantity: item.system.quantity ?? 1,
      // Loot editing prefills from these; without them a blank field on the
      // phone would look like "no value" and overwrite what is on the sheet.
      weight: Number(item.system?.weight?.value ?? 0) || 0,
      price: Number(item.system?.price?.value ?? 0) || 0,
      priceDenomination: String(item.system?.price?.denomination ?? "gp"),
      // Only what somebody wrote. It used to fall back to the weapon's stats
      // and then to the first 80 characters of the description, which put a
      // sentence fragment under half the inventory — text nobody chose, cut
      // where nobody chose, and indistinguishable from a line a player had
      // written. The stats are no loss: they travel as damageLabel and
      // rangeLabel and the phone builds that line itself.
      summary: chatDescription,
      chatDescription,
      description,
      damageLabel: formatWeaponDamageLabel(item),
      rangeLabel: formatItemRangeLabel(item),
      requiresTarget: item.type === "weapon" || (item.type === "consumable" && hasAction),
      canUse: item.type === "weapon" || hasAction || item.type === "consumable",
      // Attunement: whether the item requires it, and whether it is attuned now.
      attunementRequired: item.system?.attunement === "required",
      attuned: item.system?.attuned === true,
      // Proficiency: whether the item type has it, and the effective state
      // (the explicit override, or what the actor's proficiencies derive).
      proficiencyApplicable: "proficient" in (item.system ?? {}),
      proficient: ("proficient" in (item.system ?? {})) &&
        ((item.system.prof?.multiplier ?? item.system.proficiencyMultiplier ?? 0) > 0),
      proficiencyMode: item.system?.proficient === 0 ? "none"
        : item.system?.proficient === 1 ? "prof" : "auto",
      // Attack ability (weapons): the override, "" = derived from weapon type.
      attackAbilityApplicable: item.type === "weapon",
      attackAbility: String(item.system?.ability ?? "")
    });
  }
  // Only what could have appeared in this list. `actor.items.size` counts the
  // class, the race, the background and every feature besides, so a new
  // character with an empty pack looked like a bug to the phone.
  const inventoryCount = allItems.filter((item) => INVENTORY_TYPES.has(item.type)).length;
  return { items, currency, itemCount: inventoryCount, documentCount: actor.items.size };
}

/**
 * Journals the mobile user may read: every JournalEntry they have at least
 * OBSERVER on (GMs see all), minus the bridge's own approval-log folder. Pages
 * are filtered the same way; text pages carry HTML + a stripped preview, image
 * pages carry their src. `ownedByUser` marks entries the player can edit (their
 * own notes).
 */
/**
 * Removes unrevealed secret blocks (`<section class="secret">` without
 * `revealed`) from journal HTML for anyone who may not see them. Foundry
 * hides these with CSS the phone doesn't have, so without this the raw
 * secret text would reach the wrong users. `canSeeSecrets` is ownership-based
 * (the GM, or a user with OWNER on this specific entry) to match Foundry's
 * real secret semantics — a GM-only rule would hide a player's own secrets
 * from that same player.
 */
export function stripUnrevealedSecrets(html, canSeeSecrets) {
  if (canSeeSecrets || !html || !html.includes("secret")) return html;
  try {
    const doc = new DOMParser().parseFromString(`<body>${html}</body>`, "text/html");
    doc.body.querySelectorAll("section.secret:not(.revealed)").forEach((el) => el.remove());
    return doc.body.innerHTML;
  } catch (err) {
    return html;
  }
}

export async function listJournals(user) {
  const isGM = !!user?.isGM;
  const canRead = (doc) => isGM || doc.testUserPermission(user, "OBSERVER");
  // A leading underscore is the common convention for technical/hidden journals
  // (quest logs, calendar notes, module scratch space); keep them off the phone
  // even when a module left them observable.
  const technical = (name) => typeof name === "string" && name.startsWith("_");
  const entries = (game.journal?.contents ?? []).filter((j) => {
    if (j.folder?.name === APPROVAL_LOG_FOLDER) return false;
    if (technical(j.name)) return false;
    if (technical(j.folder?.name)) return false; // inside a technical folder
    return canRead(j);
  });
  const folders = (game.folders?.contents ?? [])
    .filter((f) => f.type === "JournalEntry" && f.name !== APPROVAL_LOG_FOLDER && !technical(f.name))
    .map((f) => ({
      id: f.id,
      name: f.name,
      parentId: f.folder?.id ?? "",
      sort: f.sort ?? 0
    }));
  // Enrich text pages so @UUID[...]{label} becomes real content-link anchors
  // (and inline rolls etc. resolve). Best-effort: fall back to the raw content.
  //
  // enrichHTML decides secret visibility from game.user (the GM tab running the
  // bridge), NOT from the mobile player, so it would happily leave secret
  // blocks in the HTML regardless of who's asking. The phone has no CSS to
  // hide them, so strip unrevealed secrets here ourselves, per entry, based on
  // whether THIS user owns THIS entry (or is a GM) — matching native Foundry's
  // "owner or GM sees secrets" rule rather than a GM-only one.
  const TE = foundry?.applications?.ux?.TextEditor?.implementation ?? globalThis.TextEditor;
  const enrich = async (raw, canSeeSecrets) => {
    if (!raw) return "";
    let html = raw;
    try {
      html = String(await TE.enrichHTML(raw, { secrets: true }));
    } catch (err) {
      html = raw;
    }
    return stripUnrevealedSecrets(html, canSeeSecrets);
  };

  const journals = [];
  for (const j of entries) {
    const ownedByUser = isGM || j.testUserPermission(user, "OWNER");
    const visiblePages = (j.pages?.contents ?? [])
      .filter((p) => canRead(p))
      .sort((a, b) => (a.sort ?? 0) - (b.sort ?? 0));
    const pages = [];
    for (const p of visiblePages) {
      const html = p.type === "text" ? await enrich(String(p.text?.content ?? ""), ownedByUser) : "";
      pages.push({
        id: p.id,
        name: p.name ?? "",
        type: p.type ?? "text",
        html,
        text: p.type === "text" ? stripHtmlText(html) : "",
        // Un-enriched source, so the note editor shows what the player typed.
        // Only sent to owners/GM: it carries the raw (unstripped) secret markup.
        raw: p.type === "text" && ownedByUser ? String(p.text?.content ?? "") : "",
        imageSrc: p.type === "image" ? routeAssetPath(String(p.src ?? "")) : ""
      });
    }
    journals.push({
      id: j.id,
      name: j.name,
      folder: j.folder?.name ?? "",
      folderId: j.folder?.id ?? "",
      ownedByUser,
      // Native ownership levels {userId: level, default: level}. Only sent for
      // entries the requester owns (or is GM on) — that's the only case the app
      // needs it, to render the share panel.
      ownership: ownedByUser ? { ...(j.ownership ?? {}) } : {},
      pages
    });
  }
  return { folders, journals };
}

/**
 * A player's note is written as plain text; wrap it as safe HTML (escaped, with
 * line breaks preserved) unless it already looks like HTML. This is what gets
 * stored as the journal page content.
 */
export function noteContentToHtml(content) {
  const s = String(content ?? "");
  if (/<[a-z][\s\S]*>/i.test(s)) return s;
  if (!s.trim()) return "";
  return `<p>${escapeHtml(s).replace(/\n/g, "<br>")}</p>`;
}

/** Create a player-owned note: a JournalEntry the player owns, with one text page. */
export async function journalNoteCreate(user, name, content) {
  const title = String(name ?? "").trim() || "Note";
  const entry = await JournalEntry.create({
    name: title,
    ownership: {
      default: CONST.DOCUMENT_OWNERSHIP_LEVELS.NONE,
      [user.id]: CONST.DOCUMENT_OWNERSHIP_LEVELS.OWNER
    },
    flags: { [MODULE_ID]: { mobileNote: true, ownerUserId: user.id } }
  });
  await entry.createEmbeddedDocuments("JournalEntryPage", [{
    name: title,
    type: "text",
    text: { content: noteContentToHtml(content), format: CONST.JOURNAL_ENTRY_PAGE_FORMATS.HTML }
  }]);
  return { accepted: true, journalId: entry.id };
}

/** Owner-only: update a note's title and body (first text page). */
export async function journalNoteSet(user, journalId, name, content) {
  const entry = game.journal.get(journalId);
  if (!entry) throw new Error("Journal not found");
  if (!(user.isGM || entry.testUserPermission(user, "OWNER"))) throw new Error("Not your journal");
  const title = name == null ? null : (String(name).trim() || entry.name);
  if (title != null) await entry.update({ name: title });
  const html = noteContentToHtml(content);
  const page = entry.pages.contents.find((p) => p.type === "text") ?? entry.pages.contents[0];
  if (page && page.type === "text") {
    const update = { "text.content": html };
    if (title != null) update.name = title;
    await page.update(update);
  } else {
    await entry.createEmbeddedDocuments("JournalEntryPage", [{
      name: title ?? entry.name,
      type: "text",
      text: { content: html, format: CONST.JOURNAL_ENTRY_PAGE_FORMATS.HTML }
    }]);
  }
  return { accepted: true };
}

/** Owner-only: delete a note. */
export async function journalNoteDelete(user, journalId) {
  const entry = game.journal.get(journalId);
  if (!entry) throw new Error("Journal not found");
  if (!(user.isGM || entry.testUserPermission(user, "OWNER"))) throw new Error("Not your journal");
  await entry.delete();
  return { accepted: true };
}

/** Ownership levels the app may assign — matches CONST.DOCUMENT_OWNERSHIP_LEVELS minus INHERIT. */
export const ASSIGNABLE_OWNERSHIP_LEVELS = new Set(["NONE", "LIMITED", "OBSERVER", "OWNER"]);

/**
 * Owner-only (or GM): grant another user a native Foundry ownership level on
 * the WHOLE entry, via `entry.update({ownership})`. Enforced server-side —
 * the requester must already be an owner (or GM); never trust the client.
 */
export async function journalOwnershipSet(user, journalId, targetUserId, level) {
  const entry = game.journal.get(journalId);
  if (!entry) throw new Error("Journal not found");
  if (!(user.isGM || entry.testUserPermission(user, "OWNER"))) throw new Error("Not your journal");
  const targetUser = game.users.get(String(targetUserId ?? ""));
  if (!targetUser) throw new Error("User not found");
  const levelKey = String(level ?? "").trim().toUpperCase();
  if (!ASSIGNABLE_OWNERSHIP_LEVELS.has(levelKey)) throw new Error(`Invalid ownership level: ${level}`);
  const ownership = { ...(entry.ownership ?? {}) };
  ownership[targetUser.id] = CONST.DOCUMENT_OWNERSHIP_LEVELS[levelKey];
  await entry.update({ ownership });
  return { accepted: true, ownership: { ...entry.ownership } };
}

/**
 * dnd5e spellcasting method (innate/atwill/ritual/spell/pact). Matches spellbook section logic.
 */
export function resolveSpellCastingMethod(sys) {
  const NON_SLOT = new Set(["atwill", "innate", "ritual", "always"]);
  let method = sys?.method;
  if (method && NON_SLOT.has(method)) {
    return method === "always" ? "innate" : method;
  }
  if (!method) {
    const prepMode = sys?.preparation?.mode;
    if (prepMode && NON_SLOT.has(prepMode)) {
      return prepMode === "always" ? "innate" : prepMode;
    }
    if (prepMode === "prepared") method = "spell";
    else if (prepMode === "always") method = "innate";
    else if (prepMode) method = prepMode;
    else method = "spell";
  }
  if (method === "prepared") method = "spell";
  if (method === "always") method = "innate";
  return method;
}

/** Spellbook section for mobile grouping (mirrors dnd5e ActorSheet5e#_prepareSpellbook). */
export function spellListSection(sys, method) {
  const NON_SLOT_METHODS = new Set(["atwill", "innate", "ritual"]);
  const level = sys?.level ?? 0;
  if (NON_SLOT_METHODS.has(method)) {
    const cfg = CONFIG.DND5E?.spellcasting?.[method] ?? {};
    const label = cfg.label ? game.i18n.localize(cfg.label) : method;
    return {
      sectionKey: method,
      sectionOrder: cfg.order ?? -100,
      sectionLabel: label,
      slotLevel: null
    };
  }
  const levelKey = CONFIG.DND5E?.spellLevels?.[level];
  const sectionLabel = levelKey
    ? game.i18n.localize(levelKey)
    : (level === 0 ? "Cantrips" : `Level ${level}`);
  return {
    sectionKey: `level:${level}`,
    sectionOrder: level,
    sectionLabel,
    slotLevel: level > 0 ? level : null
  };
}

/**
 * List all spells on the actor, grouped by spellbook section, including spell slot info.
 */
export function listSpells(user, actorId) {
  const actor = getOwnedActor(user, actorId);

  const SCHOOL_LABELS = {
    abj: "Abjuration", con: "Conjuration", div: "Divination", enc: "Enchantment",
    evo: "Evocation", ill: "Illusion", nec: "Necromancy", trs: "Transmutation"
  };

  const spells = [];
  const allItems = actor.items.contents ?? [...actor.items.values()];
  for (const item of allItems) {
    if (item.type !== "spell") continue;
    try {
      const sys = item.system;
      // dnd5e 5.1+: activation moved to activities, use first activity's activation type
      let activationType = "";
      const first = iterItemActivities(sys)[0];
      if (first) activationType = first.activation?.type ?? first.type ?? "";
      if (!activationType) activationType = sys.activation?.type ?? "";
      const uses = sys.uses ?? {};
      const usesVal = uses.spent != null ? (uses.max ?? 0) - (uses.spent ?? 0) : uses.value;
      const castingMethod = resolveSpellCastingMethod(sys);
      const section = spellListSection(sys, castingMethod);
      spells.push({
        id: item.id,
        name: item.name,
        img: routeDocumentImg(item),
        level: sys.level ?? 0,
        school: SCHOOL_LABELS[sys.school] ?? sys.school ?? "",
        preparationMode: castingMethod,
        sectionKey: section.sectionKey,
        sectionOrder: section.sectionOrder,
        sectionLabel: section.sectionLabel,
        slotLevel: section.slotLevel,
        prepared: !!sys.prepared,
        // Preparable = a leveled spell cast the "prepared" way (not a cantrip,
        // not innate/always/pact/at-will). Only these get the prepare toggle.
        canPrepare: castingMethod === "spell" && (sys.level ?? 0) > 0,
        activationType,
        usesValue: Number.isFinite(Number(usesVal)) ? Number(usesVal) : null,
        usesMax: Number.isFinite(Number(uses.max)) ? Number(uses.max) : null,
        usesLabel: uses.label ?? "",
        requiresTarget: (sys.target?.affects?.type ?? "") !== "self"
          && (sys.target?.affects?.type ?? "") !== "",
        description: stripHtmlText(sys.description?.value),
        damageLabel: formatSpellDamageLabel(item),
        rangeLabel: formatSpellRangeLabel(item),
        canUse: typeof item.use === "function",
        ...(function () {
          const tpl = resolveItemTemplateSpec(item);
          return {
            templateShape: tpl?.shape ?? null,
            templateSize: tpl?.size ?? null
          };
        })()
      });
    } catch (e) {
      console.error("[Bridge] spell error:", item.name, e);
    }
  }

  // Spell slots: spell1..spell9 + pact
  const slots = [];
  const spellData = actor.system.spells ?? {};
  for (let lvl = 1; lvl <= 9; lvl++) {
    const key = `spell${lvl}`;
    const slot = spellData[key];
    const maxSlots = slot?.override ?? slot?.max ?? 0;
    if (slot && (maxSlots > 0 || slot.value > 0)) {
      slots.push({
        key,
        level: lvl,
        value: slot.value ?? 0,
        max: maxSlots,
        label: slot.label ?? `${lvl}`
      });
    }
  }
  if (spellData.pact) {
    const pactMax = spellData.pact.override ?? spellData.pact.max ?? 0;
    if (pactMax > 0 || spellData.pact.value > 0) {
      slots.push({
        key: "pact",
        level: spellData.pact.level ?? 0,
        value: spellData.pact.value ?? 0,
        max: pactMax,
        label: spellData.pact.label ?? "Pact"
      });
    }
  }

  return { spells, slots, spellCount: spells.length };
}

export const FEATURE_SECTION_ORDER = {
  class: 10,
  race: 20,
  background: 30,
  feat: 40,
  supernaturalGift: 50,
  enchantment: 60,
  monster: 70,
  vehicle: 80
};

/**
 * List actor features (dnd5e Item type "feat"), grouped like the Features sheet tab.
 */
export function listFeatures(user, actorId) {
  const actor = getOwnedActor(user, actorId);
  const features = [];
  const allItems = actor.items.contents ?? [...actor.items.values()];
  for (const item of allItems) {
    if (item.type !== "feat") continue;
    try {
      const sys = item.system ?? {};
      const typeValue = String(sys.type?.value ?? "").trim() || "feat";
      const typeSubtype = String(sys.type?.subtype ?? "").trim();
      const typeCfg = CONFIG.DND5E?.featureTypes?.[typeValue] ?? {};
      const sectionLabel = typeCfg.label
        ? game.i18n.localize(typeCfg.label)
        : typeValue;
      let activationType = "";
      const first = iterItemActivities(sys)[0];
      if (first) activationType = first.activation?.type ?? first.type ?? "";
      if (!activationType) activationType = sys.activation?.type ?? "";
      const hasAction = !!(activationType && activationType !== "none");
      const uses = sys.uses ?? {};
      const usesVal = uses.spent != null ? (uses.max ?? 0) - (uses.spent ?? 0) : uses.value;
      const tpl = resolveItemTemplateSpec(item);
      features.push({
        id: item.id,
        name: item.name,
        img: routeDocumentImg(item),
        featureType: typeValue,
        featureSubtype: typeSubtype,
        sectionKey: typeValue,
        sectionOrder: FEATURE_SECTION_ORDER[typeValue] ?? 100,
        sectionLabel,
        activationType,
        usesValue: Number.isFinite(Number(usesVal)) ? Number(usesVal) : null,
        usesMax: Number.isFinite(Number(uses.max)) ? Number(uses.max) : null,
        usesLabel: uses.label ?? "",
        requiresTarget: (sys.target?.affects?.type ?? "") !== "self"
          && (sys.target?.affects?.type ?? "") !== "",
        description: stripHtmlText(sys.description?.value),
        damageLabel: formatSpellDamageLabel(item),
        rangeLabel: formatItemRangeLabel(item) || formatSpellRangeLabel(item),
        // A feature with charges is usable even without an activity: spending
        // one is the action. Many imported features carry uses and nothing else.
        canUse: hasAction || Number(uses.max) > 0,
        templateShape: tpl?.shape ?? null,
        templateSize: tpl?.size ?? null
      });
    } catch (e) {
      console.error("[Bridge] feature error:", item.name, e);
    }
  }
  features.sort((a, b) => {
    if (a.sectionOrder !== b.sectionOrder) return a.sectionOrder - b.sectionOrder;
    return String(a.name).localeCompare(String(b.name), undefined, { sensitivity: "base" });
  });
  return { features, featureCount: features.length };
}

export const BIOGRAPHY_SHORT_KEYS = [
  "alignment", "faith", "gender", "eyes", "hair", "skin", "height", "weight", "age"
];
export const BIOGRAPHY_LONG_KEYS = ["ideal", "bond", "flaw", "trait", "appearance"];
export const BIOGRAPHY_ALL_KEYS = new Set([...BIOGRAPHY_SHORT_KEYS, ...BIOGRAPHY_LONG_KEYS, "biography"]);

/**
 * Character biography / details tab fields (dnd5e system.details.*).
 * Biography HTML is returned as plain text for the phone editor.
 */
export function getActorBiography(user, actorId) {
  const actor = getOwnedActor(user, actorId);
  const details = actor.system?.details ?? {};
  const fields = {};
  for (const key of BIOGRAPHY_SHORT_KEYS) {
    fields[key] = String(details[key] ?? "");
  }
  for (const key of BIOGRAPHY_LONG_KEYS) {
    fields[key] = String(details[key] ?? "");
  }
  fields.biography = stripHtmlText(details.biography?.value);
  return { fields };
}

/**
 * Update one or more biography fields. `fields` is a plain object of key → string.
 * Keys: alignment, faith, gender, eyes, hair, skin, height, weight, age,
 * ideal, bond, flaw, trait, appearance, biography.
 */
export async function setActorBiography(user, actorId, fields) {
  const actor = getOwnedActor(user, actorId);
  if (!fields || typeof fields !== "object" || Array.isArray(fields)) {
    throw new Error("fields object is required");
  }
  const update = {};
  for (const [rawKey, rawVal] of Object.entries(fields)) {
    const key = String(rawKey ?? "").trim();
    if (!BIOGRAPHY_ALL_KEYS.has(key)) continue;
    const value = String(rawVal ?? "");
    if (key === "biography") {
      // Phone sends plain text; store as escaped paragraphs so Foundry sheet stays readable.
      const escaped = value
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;");
      const html = escaped
        .split(/\n{2,}/)
        .map((p) => `<p>${p.replace(/\n/g, "<br>")}</p>`)
        .join("");
      update["system.details.biography.value"] = html;
    } else {
      update[`system.details.${key}`] = value;
    }
  }
  if (Object.keys(update).length > 0) {
    await actor.update(update);
  }
  return getActorBiography(user, actorId);
}
